<template><div class="app-container"><el-form :inline="true" :model="query"><el-form-item label="状态"><el-select v-model="query.status" clearable style="width:150px"><el-option v-for="s in statuses" :key="s.value" :label="s.label" :value="s.value" /></el-select></el-form-item><el-form-item label="用户或提示词"><el-input v-model="query.keyword" clearable placeholder="手机号、邮箱或提示词" @keyup.enter="load" /></el-form-item><el-form-item><el-button type="primary" @click="load">查询</el-button></el-form-item></el-form><el-table v-loading="loading" :data="rows"><el-table-column prop="taskId" label="任务ID" width="90"/><el-table-column label="用户" width="190"><template #default="s">{{ s.row.userName || s.row.userId }}<div class="muted">{{ s.row.phoneNumber || s.row.email }}</div></template></el-table-column><el-table-column prop="taskType" label="类型" width="130"/><el-table-column prop="prompt" label="提示词" show-overflow-tooltip/><el-table-column prop="creditCost" label="算力" width="90"/><el-table-column prop="status" label="状态" width="120"><template #default="s">{{ statusLabel(s.row.status) }}</template></el-table-column><el-table-column prop="progress" label="进度" width="90"><template #default="s">{{ s.row.progress }}%</template></el-table-column><el-table-column prop="createTime" label="创建时间" width="180"/></el-table></div></template>
<script setup name="VizoraTask">
import { listTasks } from '@/api/vizora/operation'
const statuses=[{value:'QUEUED',label:'排队中'},{value:'PROCESSING',label:'处理中'},{value:'SUCCEEDED',label:'成功'},{value:'FAILED',label:'失败'},{value:'CANCELLED',label:'已取消'}]
const statusLabel=value=>statuses.find(s=>s.value===value)?.label||value
const rows=ref([]),loading=ref(false),query=reactive({status:undefined,keyword:undefined})
async function load(){loading.value=true;try{const res=await listTasks(query);rows.value=res.rows||[]}finally{loading.value=false}}load()
</script>
<style scoped>.muted{color:var(--el-text-color-secondary);font-size:12px}</style>
